import { readFileSync, readdirSync, statSync } from 'node:fs'
import { join } from 'node:path'

const root = '/home/user/deepseek-harness/.claude/worktrees/agent-a141e4f42cca3b931'

function findJsonlFiles(dir) {
  const out = []
  const stack = [dir]
  while (stack.length > 0) {
    const current = stack.pop()
    let entries
    try {
      entries = readdirSync(current)
    } catch {
      continue
    }
    for (const name of entries) {
      const full = join(current, name)
      let isDir = false
      try {
        isDir = statSync(full).isDirectory()
      } catch {
        continue
      }
      if (isDir) stack.push(full)
      else if (name.endsWith('.jsonl')) out.push(full)
    }
  }
  return out
}

const dataDir = join(root, 'data/proving-ground')
const files = findJsonlFiles(dataDir)
console.log(`scanning ${files.length} jsonl files under data/proving-ground`)

let badCount = 0
const badSamples = []
for (const file of files) {
  let text
  try {
    text = readFileSync(file, 'utf8')
  } catch {
    continue
  }
  const lines = text.split('\n')
  for (let i = 0; i < lines.length; i++) {
    const trimmed = lines[i].trim()
    if (trimmed.length === 0) continue
    let parsed
    try {
      parsed = JSON.parse(trimmed)
    } catch {
      continue
    }
    if (typeof parsed !== 'object' || parsed === null) {
      badCount++
      if (badSamples.length < 10) badSamples.push({ file, lineNo: i, reason: 'not an object', value: parsed })
      continue
    }
    if (typeof parsed.type !== 'string') {
      badCount++
      if (badSamples.length < 10) badSamples.push({ file, lineNo: i, reason: `type is ${typeof parsed.type}`, keys: Object.keys(parsed) })
    }
  }
}

console.log(`found ${badCount} lines without a string type`)
for (const sample of badSamples) {
  console.log(JSON.stringify(sample).slice(0, 400))
}

